mapper.select:
SELECT A.FXMDMB AS fxmdmb, /* 本方科目号 */ A.FXMDMD AS fxmdmd, /* 对方科目号 */ NVL(C1.SUBJECT_NAME, D1.DETAIL_SUBJECT_NAME) AS bsubjectName , /* 本方科目名称 */ NVL(C2.SUBJECT_NAME, D2.DETAIL_SUBJECT_NAME) AS dsubjectName, /* 对方科目名称 */ A.BJE AS bje, /* 本方 余额表：期末余额/估值表：市值 */ A.DJE AS dje, /* 对方 余额表：期末余额/估值表：市值 */ (A.DJE-A.BJE) AS cje, /* 差额 余额表：期末余额/估值表：市值 */ A.BSL AS bsl, /* 本方 余额表：期末数量余额/估值表：数量 */ A.DSL AS dsl, /* 对方 余额表：期末数量余额/估值表：数量 */ (A.DSL-A.BSL) AS csl, /* 差额 余额表：期末数量余额/估值表：数量 */ A.CHECK_FLAG AS checkFlag, /* 0：余额表/1：估值表 */ A.BJEO AS bjeo, /* 本方 余额表：借方发生额/估值表：成本 */ A.DJEO AS djeo, /* 对方 余额表：借方发生额/估值表：成本 */ (A.DJEO-A.BJEO) AS cjeo, /* 差额 余额表：借方发生额/估值表：成本 */ A.BJET AS bjet, /* 本方 余额表：贷方发生额/估值表：估值增值 */ A.DJET AS djet, /* 对方 余额表：贷方发生额/估值表：估值增值 */ (A.DJET-A.BJET) AS cjet /* 差额 余额表：贷方发生额/估值表：估值增值 */ FROM SZT_INTERF_RETURN_DETAIL A INNER JOIN SZT_INTERF_VALUATION B ON A.REF_NO = B.SERIALNO INNER JOIN BOK_BOOKSET BB ON BB.ACCT_SUBJECT_ID= B.FINPROD_ID LEFT JOIN BOK_SUBJECT C1 ON A.FXMDMB = C1.SUBJECT_NO AND C1.BOOKSET_ID = BB.BOOKSET_ID LEFT JOIN BOK_SUBJECT C2 ON A.FXMDMD = C2.SUBJECT_NO AND C2.BOOKSET_ID = BB.BOOKSET_ID LEFT JOIN BOK_BUSS_DETSUB D1 ON A.FXMDMB = D1.DETAIL_SUBJECT_NO AND D1.BOOKSET_ID = BB.BOOKSET_ID LEFT JOIN BOK_BUSS_DETSUB D2 ON A.FXMDMD = D2.DETAIL_SUBJECT_NO AND D2.BOOKSET_ID = BB.BOOKSET_ID WHERE A.REF_NO = #{serialNo} AND B.INTER_TYPE = #{interType}
and A.RESULT !=#{INTER_TYPE_BALANCE}
and C1.SUBJECT_LEVEL = #{subjectLevel} and D1.DETAIL_SUBJECT_NO IS NULL
and C1.SUBJECT_NO IS NULL
